  3	/**
  4	 * Tests for polling behaviour in views/project-detail.js.
  5	 *
  6	 * Covers:
  7	 *   - Inline edit survives poll ticks (WP-005 AC-5)
  8	 *   - Single-interval invariant across combined ↔ resume mode transitions (WP-005 AC-6)
  9	 *   - Modal and archive/unarchive remain functional under active polling (WP-005)
 10	 *
 11	 * Uses jsdom + vm.runInThisContext to load the browser-side scripts, then
 12	 * stubs globalThis.API and globalThis.marked to exercise the
 13	 * renderProjectDetail polling paths.
 14	 */
 15	
 16	import { describe, it, expect, beforeAll, beforeEach, afterEach, vi, type Mock } from 'vitest';
 17	import { readFileSync } from 'node:fs';
 18	import { join } from 'node:path';
 19	import vm from 'node:vm';
 20	import { makeProject } from './helpers/make-project.js';
 21	
 22	// ---------------------------------------------------------------------------
 23	// Load client scripts
 24	// ---------------------------------------------------------------------------
 25	
 26	const publicDir = join(__dirname, '../../gui/public');
 27	const projectDetailJs = readFileSync(join(publicDir, 'views/project-detail.js'), 'utf-8');
 28	
 29	beforeAll(() => {
 30	  // Install stub globals needed by project-detail.js before it is evaluated
 31	  (globalThis as Record<string, unknown>)['marked'] = {
 32	    parse: (s: string) => '<p>' + s + '</p>',
 33	  };
 34	
 35	  // OrchestratorWidgets stub
 36	  (globalThis as Record<string, unknown>)['OrchestratorWidgets'] = {
 37	    renderStatusCard:    vi.fn().mockReturnValue('<div class="orchestrator-status-card">card</div>'),
 38	    renderKillButton:    vi.fn().mockImplementation((_id: string, _cb: () => void) => {
 39	      const btn = document.createElement('button');
 40	      btn.className = 'kill-btn';
 41	      btn.textContent = 'Kill';
 42	      return btn;
 43	    }),
 44	    renderDismissButton: vi.fn(),
 45	    renderLogPreview:    vi.fn().mockReturnValue(vi.fn()), // returns a cleanup stub
 46	    renderProgressBadge: vi.fn().mockReturnValue(''),
 47	    renderCliReference:  vi.fn().mockReturnValue(''),
 48	  };
 49	
 50	  // Router stub — used by Router._setPolling() in the active run section.
 51	  (globalThis as Record<string, unknown>)['Router'] = {
 52	    _setPolling:   vi.fn(),
 53	    _clearPolling: vi.fn(),
 54	  };
 55	
 56	  vm.runInThisContext(projectDetailJs);
 57	});
 58	
 59	// Reset OrchestratorWidgets and Router mocks between tests.
 60	beforeEach(() => {
 61	  vi.clearAllMocks();
 62	  globalThis.OrchestratorWidgets.renderStatusCard
 63	    .mockReturnValue('<div class="orchestrator-status-card">card</div>');
 64	  globalThis.OrchestratorWidgets.renderKillButton
 65	    .mockImplementation((_id: string, _cb: () => void) => {
 66	      const btn = document.createElement('button');
 67	      btn.className = 'kill-btn';
 68	      btn.textContent = 'Kill';
 69	      return btn;
 70	    });
 71	  globalThis.OrchestratorWidgets.renderLogPreview.mockReturnValue(vi.fn());
 72	});
